def dedupe_keep_last(items):
    seen = set()
    last_occurrences = {}

    for index, item in enumerate(items):
        if item not in seen:
            seen.add(item)
            last_occurrences[item] = index
        else:
            last_occurrences[item] = max(last_occurrences[item], index)

    return [items[index] for index in range(len(items)) if index >= last_occurrences[items[index]]]
